from research_helpers import *
a=ev('https://www.anixa.com/pipeline','Current issuer identifies lira-cel Phase1 and breast vaccine Phase1 completed/Phase2 preparation. No approval or completed Phase2 asserted.')
b=ev('https://www.anixa.com/technologies','Issuer says lira-cel targetsFSHR and breast vaccine alpha-lactalbumin; treated patients and exploratory observations not proven efficacy or approved therapy.')
c=ev('https://ir.anixa.com/sec-filings/content/0001493152-26-001845/0001493152-26-001845.pdf','2026 issuer annual report explicitly identifies ovarian vaccine preclinical and lung/colon/prostate vaccine early discovery programmes with no human data.')
d=ev('https://www.sec.gov/Archives/edgar/data/715446/000151316217000061/prospectus.htm','Historical issuer ITUS/Anixa Diagnostics identifies investigational Cchek early-cancer immune-cell blood-test platform. No current activity/approval established.')
ps=[p('Liraltagene autoleucel','Investigational FSHR-targeted CAR-T therapy delivered intraperitoneally for recurrent/refractory ovarian cancer.',a,'development',aliases=['lira-cel'],attributes={'molecular_target':'FSHR','issuer_reported_stage':'Phase1','trial_id':'NCT05316129'},evidence=[a,b]),p('Anixa alpha-lactalbumin breast cancer vaccine','Investigational vaccine targeting alpha-lactalbumin for treatment/prevention of breast cancer; Phase1 complete, Phase2 planned.',a,'development',attributes={'molecular_target':'alpha-lactalbumin','issuer_reported_stage':'Phase1 complete; Phase2 preparation','partner':'Cleveland Clinic'},evidence=[a,b,c])]
for cancer,life in [('ovarian','research'),('lung','research'),('colon','research'),('prostate','research')]:ps.append(p('Anixa '+cancer+' cancer vaccine programme','Preclinical/discovery cancer-vaccine programme for '+cancer+' cancer; no human clinical trial or approved product established.',c,life,attributes={'identity_scope':'descriptive issuer-identified programme; no verified candidate code','historical_issuer_stage':'preclinical' if cancer=='ovarian' else 'early discovery'}))
ps.append(p('Anixa retired-protein cancer vaccine technology','Cancer-vaccine research approach targeting tissue proteins re-expressed in cancers, supporting distinct indication programmes.',b,'development',typ='technology'))
ps.append(p('Cchek','Historical investigational immune-cell profiling/AI-assisted early-cancer blood-test platform; current status unverified.',d,'unknown',typ='technology',sub='diagnostics'))
cs=[company('Anixa Biosciences Inc',ps,[a,b,c,d],'Two clinical candidates, four expressly disclosed discovery/preclinical vaccine programmes, retired-protein technology and historical Cchek reviewed. New clinical website focuses on two leads;2026 annual report supports other programmes, without invented codes/targets or human efficacy. Current legacy programme status, vaccine antigen identities and older antiviral research still need verification.')]
e=ev('https://www.adaptivebiotech.com/our-platform/','Current issuer offers immune profiling research services with humanTCRB/humanIGH/mouseTCRB guidelines, TCR antigen annotation, Connector data portal and Visualizer analysis software. Broad drug examples not owned products.')
f=ev('https://www.adaptivebiotech.com/mrd-pipeline/','Current issuer distinguishes FDA-cleared clonoSEQ for specified malignancy/specimen combinations from CLIA-validated LDT uses in other lymphoid cancers. Indications/specimens do not automatically constitute separate assay products.')
g=ev('https://www.sec.gov/Archives/edgar/data/1478320/000095017024023095/adpt-20231231.htm','Issuer states TDetect further commercialization DEFERRED in2022, revenues from TDetectCOVID in prior years; no current commercial launch or formal full discontinuation inferred.')
h=ev('https://investors.adaptivebiotech.com/static-files/3f4e7c38-d4a8-4e44-8ba6-86e1c59fa9b9','Historical issuer identifies immunoSEQ, TDetectCOVID, June2022TDetectLyme launch and immunoSEQTMAP research offerings; current brands/kit version mapping not presumed.')
i=ev('https://investors.adaptivebiotech.com/static-files/4216f4a0-e269-4e38-90aa-01a0afed8ffe','Issuer explicitly says immunoSEQTMAPCOVID research-use-only; not a clinical diagnostic or vaccine.')
ps=[p('clonoSEQ','NGS-based measurable residual disease assay for lymphoid cancers, commercial clinical and research offering.',f,'commercial',typ='product',sub='diagnostics',attributes={'FDA_cleared_uses':'bone marrow in multiple myeloma/BALL; blood or marrow in CLL','other_lymphoid_uses':'CLIA-validated LDT; not generalized FDA clearance'})]
for target,species in [('TCRB','human'),('IGH','human'),('TCRB','mouse')]:ps.append(p('Adaptive '+species+' '+target+' immunosequencing assay','Research immune-receptor deep-sequencing assay for '+species+' '+target+' repertoires.',e,'commercial',typ='product',sub='research_tools',attributes={'species':species,'target':target,'use':'research'}))
for name,desc in [('Adaptive immune medicine platform','Immune-receptor sequencing, pairing, characterization and profiling technology supporting research and diagnostics.'),('Adaptive TCR-antigen mapping platform','Immune receptor/antigen data mapping and annotation technology offered for research/partner development.'),('Adaptive Connector','Named portal for immune repertoire data access and secure two-way file sharing.'),('Adaptive Visualizer','Named software for immune repertoire exploration, visualization and research-data analysis.')]:ps.append(p(name,desc,e,'commercial',typ='technology',sub='research_tools'))
for name,desc,source in [('T-Detect COVID','Historical T-cell-response assay for prior SARSCoV2 exposure; current commercial availability unverified and franchise commercialization deferred2022.',g),('T-Detect Lyme','Historical Lyme disease T-cell assay launched June2022; current commercial availability unverified and franchise commercialization deferred.',h)]:ps.append(p(name,desc,source,'unknown',typ='product',sub='diagnostics',attributes={'franchise_activity':'further commercialization deferred in2022','current_supply':'unverified'},evidence=[g,h]))
ps.append(p('immunoSEQ T-MAP COVID','Historical research-use-only SARSCoV2-specific T-cell repertoire/antigen-mapping solution.',i,'unknown',typ='product',sub='research_tools',evidence=[h,i]))
ps.append(p('immunoSEQ','Historical branded immune-repertoire sequencing research offering; exact mapping of legacy kits/versions to current services unverified.',h,'unknown',typ='technology',sub='research_tools'))
cs.append(company('Adaptive Biotechnologies Corporation',ps,[e,f,g,h,i],'12 reviewed assay/platform/software identities:clonoSEQ,three species/target research assays,four named platform/software offerings,two historicalTDetect tests,TMAPCOVID and legacyimmunoSEQ. FDA-cleared versus LDT clonoSEQ scope retained; TDetect deferral not invented formal discontinuation. Legacy kit SKU/version relationships, any newer formulations and current proposed corporate separation/partner therapeutic assets remain to research; Genentech/Pfizer products not inferred solely from partnerships.'))
(out/'batch-0129.json').write_text(json.dumps({'companies':cs},indent=2));print(sum(len(c['products']) for c in cs))
